#!/usr/bin/env python3
import json
from docx import Document

# Load employee data
with open('/root/employee_data.json', 'r') as f:
    data = json.load(f)

# Load the Word template
doc = Document('/root/offer_letter_template.docx')

# Function to replace placeholders in text
def replace_placeholders(text, data):
    if not text:
        return text

    # Replace all placeholders
    for key, value in data.items():
        placeholder = f"{{{{{key}}}}}"
        text = text.replace(placeholder, str(value))

    return text

# Function to handle conditional sections
def handle_conditionals(text, data):
    if not text:
        return text, True

    # Check for IF_RELOCATION conditional
    if '{{IF_RELOCATION}}' in text:
        # If relocation package is Yes, remove the markers
        if data.get('RELOCATION_PACKAGE') == 'Yes':
            text = text.replace('{{IF_RELOCATION}}', '')
            text = text.replace('{{END_IF_RELOCATION}}', '')
            return text, True
        else:
            # If no relocation, mark paragraph for deletion
            return text, False

    if '{{END_IF_RELOCATION}}' in text:
        if data.get('RELOCATION_PACKAGE') == 'Yes':
            text = text.replace('{{END_IF_RELOCATION}}', '')
            return text, True
        else:
            return text, False

    return text, True

# Process all paragraphs
paragraphs_to_delete = []
in_relocation_block = False

for i, paragraph in enumerate(doc.paragraphs):
    original_text = paragraph.text

    # Check if we're entering or exiting relocation block
    if '{{IF_RELOCATION}}' in original_text:
        in_relocation_block = True
        if data.get('RELOCATION_PACKAGE') != 'Yes':
            paragraphs_to_delete.append(i)
            continue

    if '{{END_IF_RELOCATION}}' in original_text:
        if data.get('RELOCATION_PACKAGE') != 'Yes':
            paragraphs_to_delete.append(i)
        in_relocation_block = False
        continue

    # If we're in a relocation block and relocation is No, mark for deletion
    if in_relocation_block and data.get('RELOCATION_PACKAGE') != 'Yes':
        paragraphs_to_delete.append(i)
        continue

    # Handle conditionals and replace placeholders
    processed_text, keep_paragraph = handle_conditionals(original_text, data)

    if not keep_paragraph:
        paragraphs_to_delete.append(i)
        continue

    processed_text = replace_placeholders(processed_text, data)

    # Update paragraph text by updating runs
    if processed_text != original_text:
        # Clear existing runs and add new text
        for run in paragraph.runs:
            run.text = ''
        if paragraph.runs:
            paragraph.runs[0].text = processed_text
        else:
            paragraph.add_run(processed_text)

# Process tables (if any)
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                original_text = paragraph.text
                processed_text, keep = handle_conditionals(original_text, data)
                if keep:
                    processed_text = replace_placeholders(processed_text, data)
                    if processed_text != original_text:
                        for run in paragraph.runs:
                            run.text = ''
                        if paragraph.runs:
                            paragraph.runs[0].text = processed_text
                        else:
                            paragraph.add_run(processed_text)

# Delete marked paragraphs (in reverse order to maintain indices)
for i in reversed(paragraphs_to_delete):
    p = doc.paragraphs[i]
    p_element = p._element
    p_element.getparent().remove(p_element)

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print("Offer letter successfully created: /root/offer_letter_filled.docx")

